#!/usr/bin/env python3
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1] / "upstream"
client_probe = ROOT / "fabric/src/main/java/org/valkyrienskies/mod/fabric/client/GateEClientProbe.java"
source = client_probe.read_text(encoding="utf-8")

field_anchor = '''    private static boolean fixtureClientNormalized;\n'''
field_replacement = '''    private static boolean fixtureClientNormalized;\n    private static boolean fixtureColliderNormalized;\n'''
if "fixtureColliderNormalized" not in source:
    if field_anchor not in source:
        raise SystemExit("Phase 67 could not find client fixture normalization flag")
    source = source.replace(field_anchor, field_replacement, 1)

anchor = '''            var playerBox = player.getBoundingBox();\n            String simplifiedColliderState = "unresolved";'''
insert = '''            var playerBox = player.getBoundingBox();\n\n            // Phase 61 placed the smoke player on block-coordinate Y+1. Copycat and\n            // other partial shapes can have a lower real collision top. Normalize the\n            // CI-only LocalPlayer once more to the actual simplified collider surface\n            // that Create feeds into ContinuousOBBCollider. Production movement is not\n            // changed by this harness-only correction.\n            if (!fixtureColliderNormalized) {\n                try {\n                    java.lang.reflect.Method getContraptionForFixture = carriage.getClass().getMethod("getContraption");\n                    Object contraptionForFixture = getContraptionForFixture.invoke(carriage);\n                    if (contraptionForFixture != null) {\n                        java.lang.reflect.Method getSimplifiedForFixture = contraptionForFixture.getClass().getMethod("getSimplifiedEntityColliders");\n                        Object simplifiedForFixture = getSimplifiedForFixture.invoke(contraptionForFixture);\n                        if (simplifiedForFixture != null) {\n                            Class<?> listType = simplifiedForFixture.getClass();\n                            int colliderCount = listType.getField("size").getInt(simplifiedForFixture);\n                            double[] cx = (double[]) listType.getField("centerX").get(simplifiedForFixture);\n                            double[] cy = (double[]) listType.getField("centerY").get(simplifiedForFixture);\n                            double[] cz = (double[]) listType.getField("centerZ").get(simplifiedForFixture);\n                            double[] ex = (double[]) listType.getField("extentsX").get(simplifiedForFixture);\n                            double[] ey = (double[]) listType.getField("extentsY").get(simplifiedForFixture);\n                            double[] ez = (double[]) listType.getField("extentsZ").get(simplifiedForFixture);\n                            java.lang.reflect.Method toLocalFixture = carriage.getClass().getMethod("toLocalVector", Vec3.class, float.class);\n                            java.lang.reflect.Method toGlobalFixture = carriage.getClass().getMethod("toGlobalVector", Vec3.class, float.class);\n                            Vec3 localFeetFixture = (Vec3) toLocalFixture.invoke(carriage, player.position(), 0.0f);\n                            final double eps = 1.0E-5;\n                            int best = -1;\n                            double bestTop = -Double.MAX_VALUE;\n                            for (int i = 0; i < colliderCount; i++) {\n                                double minX = cx[i] - ex[i] - eps;\n                                double maxX = cx[i] + ex[i] + eps;\n                                double minZ = cz[i] - ez[i] - eps;\n                                double maxZ = cz[i] + ez[i] + eps;\n                                double top = cy[i] + ey[i];\n                                if (localFeetFixture.x < minX || localFeetFixture.x > maxX || localFeetFixture.z < minZ || localFeetFixture.z > maxZ) continue;\n                                if (top > localFeetFixture.y + 0.5) continue;\n                                if (top > bestTop) {\n                                    bestTop = top;\n                                    best = i;\n                                }\n                            }\n                            if (best >= 0) {\n                                Vec3 localTarget = new Vec3(localFeetFixture.x, bestTop + 0.05, localFeetFixture.z);\n                                Vec3 worldTarget = (Vec3) toGlobalFixture.invoke(carriage, localTarget, 0.0f);\n                                double gap = localFeetFixture.y - bestTop;\n                                fixtureColliderNormalized = true;\n                                if (Math.abs(gap - 0.05) > 0.02) {\n                                    player.setPos(worldTarget.x, worldTarget.y, worldTarget.z);\n                                    player.setDeltaMovement(Vec3.ZERO);\n                                    LOGGER.info(\n                                        "GATE_E_FIXTURE_COLLIDER_REPOSITIONED collider_index={} local_top={} old_vertical_gap={} target={},{},{}",\n                                        best, bestTop, gap, worldTarget.x, worldTarget.y, worldTarget.z);\n                                    return;\n                                } else {\n                                    LOGGER.info("GATE_E_FIXTURE_COLLIDER_ALREADY_ALIGNED collider_index={} local_top={} vertical_gap={}", best, bestTop, gap);\n                                }\n                            }\n                        }\n                    }\n                } catch (ReflectiveOperationException | RuntimeException exception) {\n                    LOGGER.info("GATE_E_FIXTURE_COLLIDER_NORMALIZE_ERROR type={}", exception.getClass().getSimpleName());\n                }\n            }\n\n            String simplifiedColliderState = "unresolved";'''
if "GATE_E_FIXTURE_COLLIDER_REPOSITIONED" not in source:
    if anchor not in source:
        raise SystemExit("Phase 67 could not find simplified collider telemetry anchor")
    source = source.replace(anchor, insert, 1)

# Make Phase 66 diagnostics tolerant of floating-point boundary noise too.
source = source.replace(
    '''if (localFeetForCollider.x >= minX && localFeetForCollider.x <= maxX && localFeetForCollider.z >= minZ && localFeetForCollider.z <= maxZ) {''',
    '''if (localFeetForCollider.x >= minX - 1.0E-5 && localFeetForCollider.x <= maxX + 1.0E-5 && localFeetForCollider.z >= minZ - 1.0E-5 && localFeetForCollider.z <= maxZ + 1.0E-5) {''',
    1)

client_probe.write_text(source, encoding="utf-8")
print("Phase 67: normalized the CI LocalPlayer to Create's actual simplified collision-surface top (with epsilon-safe X/Z containment) so narrow-phase carry is tested against the real Copycats shape; harness-only")
